// ============================================

// 同次渲染自动去重（Request Memoization）
// 同一个 URL 的 fetch 在同一次渲染中只执行一次
async function getPageData() {
  // 这两次调用只会真正发起一次请求
  const [posts, comments] = await Promise.all([
    fetch('https://api.example.com/posts').then(r => r.json()),
    fetch('https://api.example.com/posts').then(r => r.json()),
  ])
  return { posts, comments }
}

