// 路由级 revalidate 配置
// app/blog/page.tsx

// 整个路由每 30 秒重新生成
export const revalidate = 30

export default async function BlogPage() {
  const posts = await fetch('https://api.example.com/posts').then(r => r.json())
  return <h1>博客列表 ({posts.length})</h1>
}
